def power_base_sum(base, power):
    if power == 0:
        return 0
    elif power % 2 == 0:
        return power_base_sum(base, power//2) + power_base_sum(base, power//2)
    elif power % 3 == 0:
        return power_base_sum(base, power//3) + power_base_sum(base, power//3)
    elif power % 4 == 0:
        return power_base_sum(base, power//4) + power_base_sum(base, power//4)
    elif power % 5 == 0:
        return power_base_sum(base, power//5) + power_base_sum(base, power//5)
    else:
        return base + power_base_sum(base, power//2) + power_base_sum(base, power//3) + power_base_sum(base, power//4) + power_base_sum(base, power//5)

