        if x < 2:
            return False
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return False
        return True

    def is_polite(n):
        if n < 1:
            return False
        if n == 1:
            return True
        if n % 2 == 0:
            return False
        if n % 3 == 0:
            return False
        if n % 5 == 0:
